import {editorialImage} from './editorial.js';
import {icon3D} from './icons.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=icon3D;
export const labs=[['lab-colour','Light Mixer','Mix light. Find a new colour.','sun','pink'],['lab-circuit','Circuit Playground','Close the path. Notice what changes.','lightbulb','orange'],['lab-gravity','Gravity Drop','One height. Three different worlds.','orbit','purple'],['lab-gears','Gear Workshop','Turn one wheel. Watch the other.','settings-2','blue']];
export const labCards=()=>`<div class="game-grid">${labs.map(([id,t,d,i,c])=>`<a href="#/explore/${id}" class="lab-card ${c}"><div class="lab-symbol">${icon(i)}</div><span class="eyebrow">Zuno Lab · Interactive</span><h3>${t}</h3><p>${d}</p><span class="text-link">Try the idea ${icon('arrow-right')}</span></a>`).join('')}</div>`;
const notes={
 'lab-colour':{'6-8':['Mix beams of coloured light. What do you think red and green light will make?','This is light, not paint. Different kinds of mixing can give different results.'],'9-11':['Change the red, green and blue light channels. Predict a colour before moving a slider.','This is additive RGB colour mixing on a screen. Paint mixing works differently. Full red, green and blue light produces white in this model.'],'12-14':['Explore an additive RGB display model. Predict the result of equal channel values and then test it.','The numeric channels describe screen colour, not pigment recipes or a spectral measurement. Perceived colour also depends on the display and viewing conditions.']},
 'lab-circuit':{'6-8':['A circuit needs a complete path. Try opening and closing the pretend switch.','This is an on-screen model. The glowing circle is a visual clue, not a real bulb.'],'9-11':['Close the switch. Then change voltage or resistance and compare the current.','This model uses an ideal resistor and I = V ÷ R. The glow is illustrative. Real bulbs and circuits are more complicated.'],'12-14':['Investigate Ohm’s law for an ideal DC resistor: I = V/R, with power P = VI. Change one variable at a time.','The model ignores heating, component limits and internal resistance. It is not a guide or safety calculator for physical electrical work.']},
 'lab-gravity':{'6-8':['Drop the same pretend ball from the same height on different worlds. Which landing will take longer?','Our model leaves out air. Different gravity changes the fall.'],'9-11':['Compare a drop on Earth, the Moon and Mars. Keep the height the same for a fair comparison.','The model starts from rest and ignores air resistance. The same screen distance represents the same chosen height.'],'12-14':['Compare t = √(2h/g) for an ideal drop from rest. Change gravity or height, then predict the change in fall time.','Uniform gravity, no drag, no initial velocity and a fixed height are model assumptions. This is not a simulation of every real falling object.']},
 'lab-gears':{'6-8':['Turn the small gear. Which way does the bigger one turn? Can you see which turns more slowly?','These two outside gears touch. They turn in opposite directions.'],'9-11':['Compare the tooth counts. A driver with 12 teeth turning a 24-tooth gear makes the larger gear rotate half as fast.','This ideal model shows two external gears. It ignores friction and does not simulate a real machine’s safety or strength.'],'12-14':['For two meshing external gears, ω₂ = −ω₁N₁/N₂. Investigate tooth count, speed ratio and direction.','Equal tooth spacing is assumed. The diagram is illustrative, not a manufacturing design. Torque and efficiency are not modelled.']}
};
export function labPage(id,age){const lab=labs.find(x=>x[0]===id);if(!lab)return '';return `<a class="back" href="#/explore">${icon('arrow-left')}All worlds & labs</a><div class="page-intro"><div><div class="eyebrow">Zuno Lab · Ages ${age}</div><h1>${lab[1]}</h1><p>${notes[id][age][0]}</p></div></div><section class="lab-workspace" id="lab-workspace"></section><div class="callout">${icon('lightbulb')}<p>${notes[id][age][1]}</p></div><div class="mini-panel"><h2>Make a little discovery</h2><p>${age==='6-8'?'Say what you think will happen. Try one change. Tell someone what you noticed.':age==='9-11'?'Predict a result, change one thing and compare what happened. What would you try next?':'State a prediction, identify the controlled variables, test one change and describe where the model’s assumptions limit your conclusion.'}</p><a class="text-link" href="#/discover/${id==='lab-colour'?'patterns':id==='lab-circuit'?'electricity':id==='lab-gravity'?'solar-system':'algorithms'}">Read the connected discovery ${icon('arrow-right')}</a></div>`;}
const range=(id,label,value,min,max,step=1)=>`<label class="lab-range" for="${id}"><span>${label} <output id="${id}-value">${value}</output></span><input id="${id}" type="range" aria-label="${label}" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;
const choice=(key,value,label,selected)=>`<button class="chip ${selected?'active':''}" data-${key}="${value}" aria-pressed="${!!selected}">${label}</button>`;
export function mountLab(id,{age,reduced=false}){
 const root=document.querySelector('#lab-workspace');if(!root)return()=>{};const abort=new AbortController();let frame=0,stopped=false;
 const listen=(el,event,fn)=>el.addEventListener(event,fn,{signal:abort.signal});const by=id=>root.querySelector('#'+id);
 if(id==='lab-colour'){
  root.innerHTML=`<div class="light-stage"><div class="light-beam red"></div><div class="light-beam green"></div><div class="light-beam blue"></div><div id="mixed-light" class="mixed-light"></div><span class="lab-stage-caption">Your screen-light mixture</span></div><div class="lab-controls"><h2>What colour will you make?</h2>${range('red-light','Red',180,0,255,age==='6-8'?85:1)}${range('green-light','Green',85,0,255,age==='6-8'?85:1)}${range('blue-light','Blue',180,0,255,age==='6-8'?85:1)}<div class="lab-result" id="colour-result" aria-live="polite"></div><button class="button light" id="all-light">Try all three at full brightness</button></div>`;
  const paint=()=>{const vals=['red','green','blue'].map(n=>{const v=+by(n+'-light').value;by(n+'-light-value').textContent=v;root.querySelector('.light-beam.'+n).style.opacity=v/255;return v});by('mixed-light').style.background=`rgb(${vals.join(',')})`;by('mixed-light').style.boxShadow=`0 0 65px rgba(${vals.join(',')},.25)`;by('colour-result').textContent=age==='6-8'?(vals.every(x=>x===255)?'All three make white light here!':'Try a change and watch the mixture.'):'RGB ('+vals.join(', ')+')'+(age==='12-14'?' · #'+vals.map(x=>x.toString(16).padStart(2,'0')).join('').toUpperCase():'');};
  listen(root,'input',paint);listen(by('all-light'),'click',()=>{['red','green','blue'].forEach(n=>by(n+'-light').value=255);paint()});paint();
 }else if(id==='lab-circuit'){
  let closed=true;root.innerHTML=`<div class="circuit-stage" id="circuit-visual"></div><div class="lab-controls"><h2>Find the complete path</h2><button class="button light" id="circuit-switch" role="switch" aria-checked="true">Open the switch</button>${range('voltage','Voltage (V)',6,1,12,1)}${age==='6-8'?'<input type="hidden" id="resistance" value="20">':range('resistance','Resistance (Ω)',20,10,100,5)}<div class="lab-result" id="circuit-result" aria-live="polite"></div></div>`;
  const paint=()=>{const v=+by('voltage').value,r=+by('resistance').value,i=closed?v/r:0;by('voltage-value').textContent=v;if(by('resistance-value'))by('resistance-value').textContent=r;by('circuit-switch').textContent=closed?'Open the switch':'Close the switch';by('circuit-switch').setAttribute('aria-checked',String(closed));by('circuit-result').textContent=age==='6-8'?(closed?'A complete path. The indicator glows!':'The path is open. No current flows.'):`Current: ${i.toFixed(2)} A`+(age==='12-14'?` · Power: ${(v*i).toFixed(2)} W`:'');by('circuit-visual').innerHTML=`<svg viewBox="0 0 400 280" role="img" aria-label="${closed?'Closed':'Open'} ideal circuit with battery, switch and resistor indicator"><path d="M75 145V65H177M223 65H325V220H75V170" fill="none" stroke="${closed?'#738aff':'#929ab3'}" stroke-width="7" stroke-linecap="round"/><path d="M177 65L223 ${closed?'65':'35'}" stroke="#ffb800" stroke-width="7" stroke-linecap="round"/><path d="M48 145H102M58 170H92" stroke="#9b85ed" stroke-width="7"/><circle cx="325" cy="150" r="38" fill="${closed?'#ffcf55':'#939bb5'}" opacity="${closed ? .3+Math.min(.7,i*1.2) : .3}"/><path d="M315 130L335 140L315 150L335 160L325 173" stroke="#5e4a1c" stroke-width="3" fill="none"/><text x="90" y="255" fill="currentColor" font-size="13">${v} V</text><text x="250" y="255" fill="currentColor" font-size="13">${r} Ω · ideal resistor</text></svg>`};listen(root,'input',paint);listen(by('circuit-switch'),'click',()=>{closed=!closed;paint()});paint();
 }else if(id==='lab-gravity'){
  let gravity=9.81,planet='Earth',running=false;root.innerHTML=`<div class="gravity-stage"><div class="drop-ball" id="drop-ball"></div><div class="drop-ground"></div><span class="lab-stage-caption">Same starting height · no air resistance</span></div><div class="lab-controls"><h2>Choose your world</h2><div class="filter-row">${[['Earth',9.81],['Moon',1.62],['Mars',3.71]].map(([n,g])=>choice('gravity',g,n,n==='Earth')).join('')}</div>${age==='12-14'?range('drop-height','Height (m)',3,1,10):'<input id="drop-height" type="hidden" value="3">'}<button class="button" id="drop-button">${icon('play')}Drop the ball</button><div class="lab-result" id="drop-result" aria-live="polite">Make a prediction, then try a drop.</div></div>`;
  const update=()=>{if(by('drop-height-value'))by('drop-height-value').textContent=by('drop-height').value;};listen(root,'input',update);listen(root,'click',e=>{const b=e.target.closest('[data-gravity]');if(!b||running)return;gravity=+b.dataset.gravity;planet=b.textContent;root.querySelectorAll('[data-gravity]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});by('drop-ball').style.transform='translateY(0)';by('drop-result').textContent='Ready to compare a drop on '+planet+'.';});
  listen(by('drop-button'),'click',()=>{if(running)return;const h=+by('drop-height').value,t=Math.sqrt(2*h/gravity);running=true;by('drop-button').disabled=true;root.querySelectorAll('[data-gravity],#drop-height').forEach(x=>x.disabled=true);const start=performance.now(),finish=()=>{running=false;by('drop-button').disabled=false;root.querySelectorAll('[data-gravity],#drop-height').forEach(x=>x.disabled=false);by('drop-result').textContent=age==='6-8'?'Landed on '+planet+'. Try another world and compare.':`${planet}: ${t.toFixed(2)} seconds for ${h} m in this ideal model.`};function draw(now){if(stopped)return;const seconds=reduced?t:Math.min(t,(now-start)/1000),y=Math.min(190,.5*gravity*seconds*seconds/h*190);by('drop-ball').style.transform=`translateY(${y}px)`;if(seconds<t)frame=requestAnimationFrame(draw);else finish()}frame=requestAnimationFrame(draw)});
 }else if(id==='lab-gears'){
  let teeth=24,paused=reduced,angle=0,last=performance.now();root.innerHTML=`<div class="gear-stage" id="gear-visual"></div><div class="lab-controls"><h2>One gear drives another</h2>${range('gear-speed','Driver speed (rpm)',20,5,60,5)}${age==='6-8'?'<p class="reading-level">12 teeth drive 24 teeth.</p>':`<div class="filter-row">${[12,18,24].map(n=>choice('teeth',n,n+' driven teeth',n===24)).join('')}</div>`}<button class="button light" id="gear-pause">${paused?'Start turning':'Pause gears'}</button><div class="lab-result" id="gear-result" aria-live="polite"></div></div>`;
  const gear=(n,r,cx)=>{let d='';for(let j=0;j<n*4;j++){const a=j/(n*4)*Math.PI*2,rr=j%4===1||j%4===2?r+4:r-3;d+=(j?'L':'M')+(cx+Math.cos(a)*rr).toFixed(2)+','+(110+Math.sin(a)*rr).toFixed(2)}return d+'Z'};
  const paint=()=>{const r2=teeth*3,c2=100+36+r2;by('gear-visual').innerHTML=`<svg viewBox="0 0 380 220" role="img" aria-label="A 12-tooth driver meshes with a ${teeth}-tooth driven gear"><g id="driver-gear"><path d="${gear(12,36,100)}" fill="#7968f1"/><circle cx="100" cy="110" r="10" fill="#ece8ff"/></g><g id="driven-gear"><path d="${gear(teeth,r2,c2)}" fill="#18b6c3"/><circle cx="${c2}" cy="110" r="10" fill="#ddfaff"/></g></svg>`;by('gear-speed-value').textContent=by('gear-speed').value;by('gear-result').textContent=age==='6-8'?'The big gear turns more slowly, in the opposite direction.':`Driven speed: ${(+by('gear-speed').value*12/teeth).toFixed(1)} rpm · opposite direction`+(age==='12-14'?` · tooth ratio 12:${teeth}`:'');};
  listen(root,'input',paint);listen(root,'click',e=>{const b=e.target.closest('[data-teeth]');if(!b)return;teeth=+b.dataset.teeth;root.querySelectorAll('[data-teeth]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});paint()});listen(by('gear-pause'),'click',()=>{paused=!paused;by('gear-pause').textContent=paused?'Start turning':'Pause gears'});paint();function animate(now){if(stopped)return;const dt=Math.min((now-last)/1000,.05);last=now;if(!paused&&!document.hidden)angle+=dt*(+by('gear-speed').value)*6;by('driver-gear')?.setAttribute('transform',`rotate(${angle} 100 110)`);by('driven-gear')?.setAttribute('transform',`rotate(${-angle*12/teeth} ${136+teeth*3} 110)`);frame=requestAnimationFrame(animate)}frame=requestAnimationFrame(animate);
 }
 return()=>{stopped=true;cancelAnimationFrame(frame);abort.abort()};
}
const timeline=[['1940','A Kenyan changemaker is born.','Wangari Maathai was born in Kenya in 1940.'],['1977','An idea takes root.','She founded the Green Belt Movement, bringing community tree planting and environmental action together.'],['2004','The Nobel Peace Prize.','Maathai received the Nobel Peace Prize for her contribution to sustainable development, democracy and peace.'],['2011','A lasting legacy.','She died in 2011. Her work remains an important story about community action and caring for the environment.']];
export function kenyaPage(age){return `<a class="back" href="#/explore">${icon('arrow-left')}All worlds</a><div class="page-intro"><div><div class="eyebrow">Explore Kenya · Ages ${age}</div><h1>Every place has a story.</h1><p>Tap a county, search for a place, or follow a Kenyan changemaker’s timeline.</p></div></div>${editorialImage({id:'kenya-photo',category:'kenya'},true)}<div class="kenya-layout"><section class="kenya-map-panel"><div id="kenya-map" class="kenya-map"><p>Opening the learning map…</p></div><p class="reading-level">47 counties · Simplified learning map · geoBoundaries / RCMRD / Africa GeoPortal</p></section><section class="mini-panel county-guide"><label class="search-label" for="county-search">Find a county</label><input type="search" id="county-search" class="county-search" placeholder="Try Nairobi, Kilifi, Kisumu…"><div class="county-results" id="county-results"></div><div id="county-story" aria-live="polite"></div></section></div><section class="timeline-panel"><div class="eyebrow">A story across time</div><h2>Wangari Maathai: an idea that grew.</h2><div class="timeline-track" aria-label="Choose a year">${timeline.map(([year],i)=>choice('year',i,year,i===0)).join('')}</div><div id="timeline-story" aria-live="polite"><h3>${timeline[0][1]}</h3><p>${timeline[0][2]}</p></div><a class="text-link" href="#/discover/wangari">Read her story ${icon('arrow-right')}</a><p class="reading-level">Reference: NobelPrize.org · Timeline is a learning selection, not a complete biography.</p></section><div class="school-card"><h2>Rooted here. Open to the world.</h2><p>Kenyan places connect to ideas that travel: ecology, geology, community, invention and conservation.</p><div class="school-topics"><a class="chip" href="#/discover/rift-valley">Landscapes</a><a class="chip" href="#/discover/rhinos">Wildlife</a><a class="chip" href="#/discover/coral">The coast</a></div></div>`;}
export async function mountKenya(age){
 const root=document.querySelector('#kenya-map');if(!root)return;const response=await fetch('/assets/maps/kenya-counties.geojson');if(!response.ok)throw Error('Map unavailable');const data=await response.json();if(!root.isConnected)return;let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;const rings=f=>f.geometry.type==='Polygon'?f.geometry.coordinates:f.geometry.coordinates.flat();for(const f of data.features)for(const ring of rings(f))for(const [x,y]of ring){minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y)}const scale=Math.min(430/(maxX-minX),520/(maxY-minY)),project=([x,y])=>[(x-minX)*scale+25,(maxY-y)*scale+25];
 const path=f=>rings(f).map(r=>r.map((p,i)=>{const [x,y]=project(p);return(i?'L':'M')+x.toFixed(1)+','+y.toFixed(1)}).join('')+'Z').join('');root.innerHTML=`<svg viewBox="0 0 ${(maxX-minX)*scale+50} ${(maxY-minY)*scale+50}" role="group" aria-label="Kenya’s 47 counties">${data.features.map((f,i)=>`<path class="county" data-county="${i}" d="${path(f)}" tabindex="0" role="button" aria-pressed="false" aria-label="${esc(f.properties.shapeName)}"><title>${esc(f.properties.shapeName)}</title></path>`).join('')}</svg>`;
 const stories={nairobi:'Nairobi is Kenya’s capital city. A city can connect people, transport, science, culture and ideas.',mombasa:'Mombasa is on Kenya’s Indian Ocean coast. Coastal places connect land, sea, trade and history.',kisumu:'Kisumu lies by Lake Victoria. Freshwater habitats connect people, plants and animals.',nakuru:'Nakuru is part of Kenya’s Rift Valley landscape. Its surroundings offer questions about geology, lakes and wildlife.',turkana:'Turkana includes part of the Lake Turkana region in northern Kenya. Landscapes and water shape many different ways of life.',narok:'Narok includes the Maasai Mara region. Wildlife habitats are also connected to people and land use.',kilifi:'Kilifi is on the Indian Ocean coast. It connects to questions about coastal habitats and marine life.'};
 const panel=document.querySelector('#county-story'),result=document.querySelector('#county-results'),input=document.querySelector('#county-search');const select=i=>{const name=data.features[i].properties.shapeName,key=Object.keys(stories).find(k=>name.toLowerCase().startsWith(k));root.querySelectorAll('[data-county]').forEach(el=>{const active=+el.dataset.county===i;el.classList.toggle('selected',active);el.setAttribute('aria-pressed',String(active))});panel.innerHTML=`<div class="eyebrow">Kenya · County discovery</div><h2>${esc(name)}</h2><p>${key?stories[key]:esc(name)+' is one of Kenya’s 47 counties. Explore its position on the map, then compare it with another county.'}</p><div class="fact-inline">${age==='6-8'?'Can you find a neighbouring county?':age==='9-11'?'What can a map tell you, and what would you need another source to learn?':'A boundary map does not describe everyone’s culture, language or experience. What additional sources would help you understand a place?'}</div>`};
 const list=()=>{const q=input.value.trim().toLowerCase();result.innerHTML=data.features.map((f,i)=>({name:f.properties.shapeName,i})).filter(x=>q?x.name.toLowerCase().includes(q):['Nairobi','Mombasa','Kisumu','Nakuru','Turkana'].some(n=>x.name.startsWith(n))).slice(0,8).map(x=>choice('county-pick',x.i,esc(x.name),false)).join('')||'<p class="reading-level">No county found. Try another spelling.</p>'};list();select(Math.max(0,data.features.findIndex(f=>f.properties.shapeName.toLowerCase().startsWith('nairobi'))));root.addEventListener('click',e=>{const p=e.target.closest('[data-county]');if(p)select(+p.dataset.county)});root.addEventListener('keydown',e=>{const p=e.target.closest('[data-county]');if(p&&['Enter',' '].includes(e.key)){e.preventDefault();select(+p.dataset.county)}});input.addEventListener('input',list);result.addEventListener('click',e=>{const p=e.target.closest('[data-county-pick]');if(p)select(+p.dataset.countyPick)});document.querySelector('.timeline-track')?.addEventListener('click',e=>{const p=e.target.closest('[data-year]');if(!p)return;const row=timeline[+p.dataset.year];document.querySelectorAll('[data-year]').forEach(x=>{x.classList.toggle('active',x===p);x.setAttribute('aria-pressed',String(x===p))});document.querySelector('#timeline-story').innerHTML=`<h3>${row[1]}</h3><p>${row[2]}${age==='12-14'?' A timeline selects events; it does not capture every cause, perspective or contribution.':''}</p>`});
}
